from pathlib import Path
import sys
root=Path(sys.argv[1])
base=root/'app/src/main/java/kz/kairat/organizer'
ui=base/'OrganizerUi.kt'
cloud=base/'CloudSync.kt'
backup=base/'BackupManager.kt'
strings=base/'AppStrings.kt'
gradle=root/'app/build.gradle.kts'

# Backup ZIP support.
b=backup.read_text()
assert 'import java.util.Locale\n' in b
b=b.replace('import java.util.Locale\n','import java.util.Locale\nimport java.util.zip.ZipEntry\nimport java.util.zip.ZipInputStream\nimport java.util.zip.ZipOutputStream\n',1)
old='''    fun writeToUri(context:Context,uri:Uri,json:String){context.contentResolver.openOutputStream(uri,"wt")!!.bufferedWriter().use{it.write(json)}}\n    fun readFromUri(context:Context,uri:Uri):String=context.contentResolver.openInputStream(uri)!!.bufferedReader().use{it.readText()}\n'''
new='''    fun writeToUri(context:Context,uri:Uri,json:String){context.contentResolver.openOutputStream(uri,"wt")!!.bufferedWriter().use{it.write(json)}}\n    fun writeArchiveToUri(context:Context,uri:Uri,json:String){\n        context.contentResolver.openOutputStream(uri,"w")!!.use{raw->\n            ZipOutputStream(raw.buffered()).use{zip->\n                zip.putNextEntry(ZipEntry(suggestedFileName(false)))\n                zip.write(json.toByteArray(Charsets.UTF_8))\n                zip.closeEntry()\n            }\n        }\n    }\n    fun readFromUri(context:Context,uri:Uri):String{\n        val bytes=context.contentResolver.openInputStream(uri)!!.use{it.readBytes()}\n        val zipped=bytes.size>=4&&bytes[0]==0x50.toByte()&&bytes[1]==0x4b.toByte()\n        if(!zipped)return bytes.toString(Charsets.UTF_8)\n        ZipInputStream(bytes.inputStream()).use{zip->\n            var entry=zip.nextEntry\n            while(entry!=null){\n                if(!entry.isDirectory)return zip.readBytes().toString(Charsets.UTF_8)\n                entry=zip.nextEntry\n            }\n        }\n        throw IllegalArgumentException("Empty backup archive")\n    }\n'''
assert old in b
b=b.replace(old,new,1)
old='''    fun suggestedFileName()="my_organizer_backup_${SimpleDateFormat("yyyyMMdd_HHmm",Locale.US).format(Date())}.json"\n'''
new='''    fun suggestedFileName(archived:Boolean=false):String{\n        val ext=if(archived)"zip" else "json"\n        return "my_organizer_backup_${SimpleDateFormat("yyyyMMdd_HHmm",Locale.US).format(Date())}.$ext"\n    }\n'''
assert old in b
b=b.replace(old,new,1)
backup.write_text(b)

# Settings page: one-screen compact layout at minimum font + save/archive row.
u=ui.read_text()
old='''    val context=LocalContext.current;var msg by remember{mutableStateOf<String?>(null)};var showPin by remember{mutableStateOf(false)};var showDisablePin by remember{mutableStateOf(false)};var showChangePin by remember{mutableStateOf(false)};var languageMenu by remember{mutableStateOf(false)}\n    val compactSettings=kotlin.math.max(fontScale,buttonScale)<=1.16f\n    val settingsOuterV=if(compactSettings)2.dp else 4.dp\n    val settingsGap=if(compactSettings)3.dp else 4.dp\n    val topCardPad=if(compactSettings)3.dp else 5.dp\n    val controlsCardPad=if(compactSettings)2.dp else 4.dp\n    val pinCardPad=if(compactSettings)2.dp else 4.dp\n    val backupCardPad=if(compactSettings)3.dp else 5.dp\n    val infoCardPad=if(compactSettings)3.dp else 5.dp\n    val saveBackup=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/json")){uri->uri?.let{runCatching{val j=BackupManager.createBackup(db,settings);BackupManager.writeToUri(context,it,j);settings.lastBackupAt=System.currentTimeMillis()}.onSuccess{msg=AppStrings.t(lang,"backup_ok")}.onFailure{e->msg=e.message}}}\n'''
new='''    val context=LocalContext.current;var msg by remember{mutableStateOf<String?>(null)};var showPin by remember{mutableStateOf(false)};var showDisablePin by remember{mutableStateOf(false)};var showChangePin by remember{mutableStateOf(false)};var languageMenu by remember{mutableStateOf(false)};var archiveBackup by rememberSaveable{mutableStateOf(false)}\n    val compactSettings=kotlin.math.max(fontScale,buttonScale)<=1.16f\n    val onePageSettings=fontScale<=.90f&&buttonScale<=.90f\n    val settingsOuterV=if(onePageSettings)0.dp else if(compactSettings)2.dp else 4.dp\n    val settingsGap=if(onePageSettings)1.dp else if(compactSettings)3.dp else 4.dp\n    val topCardPad=if(onePageSettings)1.dp else if(compactSettings)3.dp else 5.dp\n    val controlsCardPad=if(onePageSettings)0.dp else if(compactSettings)2.dp else 4.dp\n    val pinCardPad=if(onePageSettings)0.dp else if(compactSettings)2.dp else 4.dp\n    val backupCardPad=if(onePageSettings)1.dp else if(compactSettings)3.dp else 5.dp\n    val infoCardPad=if(onePageSettings)1.dp else if(compactSettings)3.dp else 5.dp\n    val saveBackup=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("*/*")){uri->uri?.let{runCatching{val j=BackupManager.createBackup(db,settings);if(archiveBackup)BackupManager.writeArchiveToUri(context,it,j)else BackupManager.writeToUri(context,it,j);settings.lastBackupAt=System.currentTimeMillis()}.onSuccess{msg=AppStrings.t(lang,"backup_ok")}.onFailure{e->msg=e.message}}}\n'''
assert old in u
u=u.replace(old,new,1)
u=u.replace('AppLogo(Modifier.size(if(compactSettings)38.dp else 42.dp))','AppLogo(Modifier.size(if(onePageSettings)34.dp else if(compactSettings)38.dp else 42.dp))',1)
u=u.replace('modifier=Modifier.size(if(compactSettings)40.dp else 44.dp)','modifier=Modifier.size(if(onePageSettings)36.dp else if(compactSettings)40.dp else 44.dp)',1)
u=u.replace('Icon(Icons.Default.Language,null,Modifier.size(if(compactSettings)21.dp else 23.dp))','Icon(Icons.Default.Language,null,Modifier.size(if(onePageSettings)19.dp else if(compactSettings)21.dp else 23.dp))',1)
old='''        item{SettingsCard("",verticalPadding=backupCardPad,spacing=if(compactSettings)2.dp else 4.dp){OutlinedButton({openBackup.launch(arrayOf("application/json","text/plain","*/*"))},Modifier.fillMaxWidth().heightIn(min=if(compactSettings)32.dp else 36.dp),contentPadding=PaddingValues(horizontal=8.dp,vertical=0.dp)){Text(AppStrings.t(lang,"restore"),maxLines=2,textAlign=androidx.compose.ui.text.style.TextAlign.Center)}}}\n        item{CloudSyncSettingsCard(db,settings,lang)}\n'''
new='''        item{SettingsCard("",verticalPadding=backupCardPad,spacing=if(onePageSettings)0.dp else if(compactSettings)2.dp else 4.dp){\n            Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(if(onePageSettings)2.dp else 4.dp)){\n                OutlinedButton({saveBackup.launch(BackupManager.suggestedFileName(archiveBackup))},Modifier.weight(1.05f).heightIn(min=if(onePageSettings)28.dp else if(compactSettings)32.dp else 36.dp),contentPadding=PaddingValues(horizontal=4.dp,vertical=0.dp)){Text(AppStrings.t(lang,"save_backup"),maxLines=2,textAlign=androidx.compose.ui.text.style.TextAlign.Center)}\n                OutlinedButton({openBackup.launch(arrayOf("application/json","application/zip","text/plain","*/*"))},Modifier.weight(1.05f).heightIn(min=if(onePageSettings)28.dp else if(compactSettings)32.dp else 36.dp),contentPadding=PaddingValues(horizontal=4.dp,vertical=0.dp)){Text(AppStrings.t(lang,"restore"),maxLines=2,textAlign=androidx.compose.ui.text.style.TextAlign.Center)}\n                Row(Modifier.weight(.9f),verticalAlignment=Alignment.CenterVertically){\n                    Text(AppStrings.t(lang,"archive_backup"),Modifier.weight(1f),maxLines=2,style=MaterialTheme.typography.bodySmall)\n                    Checkbox(archiveBackup,{archiveBackup=it},modifier=Modifier.size(if(onePageSettings)28.dp else 32.dp))\n                }\n            }\n        }}\n        item{CloudSyncSettingsCard(db,settings,lang,compactSettings)}\n'''
assert old in u
u=u.replace(old,new,1)
old='''        item{SettingsCard("",verticalPadding=controlsCardPad,spacing=if(compactSettings)1.dp else 2.dp){\n            Text(if(AppStrings.normalizeLanguage(lang)=="ru") "Веб-версия Органайзер Про" else "Organizer Pro Web",style=MaterialTheme.typography.titleSmall)\n            TextButton(onClick={webUriHandler.openUri("https://organizer-pro.onrender.com")},modifier=Modifier.fillMaxWidth()){\n                Text("https://organizer-pro.onrender.com",maxLines=2)\n            }\n        }}\n'''
new='''        item{SettingsCard("",verticalPadding=controlsCardPad,spacing=if(compactSettings)1.dp else 2.dp){\n            if(onePageSettings){\n                Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){\n                    Text(if(AppStrings.normalizeLanguage(lang)=="ru") "Веб-версия Органайзер Про" else "Organizer Pro Web",Modifier.weight(1f),style=MaterialTheme.typography.titleSmall,maxLines=1)\n                    TextButton(onClick={webUriHandler.openUri("https://organizer-pro.onrender.com")},modifier=Modifier.heightIn(min=28.dp),contentPadding=PaddingValues(horizontal=8.dp,vertical=0.dp)){Text(AppStrings.t(lang,"open"),maxLines=1)}\n                }\n            }else{\n                Text(if(AppStrings.normalizeLanguage(lang)=="ru") "Веб-версия Органайзер Про" else "Organizer Pro Web",style=MaterialTheme.typography.titleSmall)\n                TextButton(onClick={webUriHandler.openUri("https://organizer-pro.onrender.com")},modifier=Modifier.fillMaxWidth()){Text("https://organizer-pro.onrender.com",maxLines=2)}\n            }\n        }}\n'''
assert old in u
u=u.replace(old,new,1)
old='''    Row(Modifier.fillMaxWidth().heightIn(min=if(scale<=1.16f)32.dp else 36.dp),verticalAlignment=Alignment.CenterVertically){Text(label,Modifier.weight(1f),maxLines=2);Switch(value,onChange)}\n'''
new='''    Row(Modifier.fillMaxWidth().heightIn(min=if(scale<=.90f)28.dp else if(scale<=1.16f)32.dp else 36.dp),verticalAlignment=Alignment.CenterVertically){Text(label,Modifier.weight(1f),maxLines=2);Switch(value,onChange)}\n'''
assert old in u
u=u.replace(old,new,1)
ui.write_text(u)

# Account/login card in the same visual language as settings cards.
c=cloud.read_text()
c=c.replace('@Composable fun CloudSyncSettingsCard(db:NoteDatabase,settings:SettingsStore,lang:String){','@Composable fun CloudSyncSettingsCard(db:NoteDatabase,settings:SettingsStore,lang:String,compact:Boolean=false){',1)
old='''    Card(Modifier.fillMaxWidth(),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.primaryContainer)){\n        if(!logged){\n            Column(Modifier.padding(horizontal=10.dp,vertical=8.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){\n                Text(syncText(lang,"title"),style=MaterialTheme.typography.titleMedium)\n                OutlinedTextField(email,{email=it},Modifier.fillMaxWidth(),label={Text(syncText(lang,"email"))},singleLine=true)\n                OutlinedTextField(password,{password=it},Modifier.fillMaxWidth(),label={Text(syncText(lang,"password"))},singleLine=true,visualTransformation=PasswordVisualTransformation())\n                Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){\n                    Button({doLogin(false)},Modifier.weight(1f),enabled=!busy){Text(syncText(lang,"login"),maxLines=1)}\n                    OutlinedButton({doLogin(true)},Modifier.weight(1f),enabled=!busy){Text(syncText(lang,"register"),maxLines=2)}\n                }\n                if(status.isNotBlank())Text(status,color=if(error)MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary,style=MaterialTheme.typography.bodySmall)\n            }\n        }else{\n            Row(Modifier.fillMaxWidth().padding(horizontal=10.dp,vertical=5.dp),verticalAlignment=androidx.compose.ui.Alignment.CenterVertically){\n                Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(1.dp)){\n                    Text(syncText(lang,"title"),style=MaterialTheme.typography.titleSmall)\n                    Text(settings.syncEmail,style=MaterialTheme.typography.bodySmall,maxLines=1)\n                    Text(if(status.isNotBlank())status else syncText(lang,"enabled"),color=if(error)MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary,style=MaterialTheme.typography.labelMedium,maxLines=1)\n                }\n                TextButton({CloudSync.logout(settings);logged=false;status=""},enabled=!busy,modifier=Modifier.heightIn(min=30.dp),contentPadding=PaddingValues(horizontal=10.dp,vertical=0.dp)){Text(syncText(lang,"logout"),style=MaterialTheme.typography.bodySmall)}\n            }\n        }\n    }\n'''
new='''    Card(Modifier.fillMaxWidth(),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.primaryContainer)){\n        if(!logged){\n            Column(Modifier.padding(horizontal=10.dp,vertical=if(compact)4.dp else 8.dp),verticalArrangement=Arrangement.spacedBy(if(compact)3.dp else 6.dp)){\n                Text(syncText(lang,"title"),style=if(compact)MaterialTheme.typography.titleSmall else MaterialTheme.typography.titleMedium)\n                if(compact){\n                    Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(5.dp)){\n                        OutlinedTextField(email,{email=it},Modifier.weight(1f),label={Text(syncText(lang,"email"))},singleLine=true)\n                        OutlinedTextField(password,{password=it},Modifier.weight(1f),label={Text(syncText(lang,"password"))},singleLine=true,visualTransformation=PasswordVisualTransformation())\n                    }\n                }else{\n                    OutlinedTextField(email,{email=it},Modifier.fillMaxWidth(),label={Text(syncText(lang,"email"))},singleLine=true)\n                    OutlinedTextField(password,{password=it},Modifier.fillMaxWidth(),label={Text(syncText(lang,"password"))},singleLine=true,visualTransformation=PasswordVisualTransformation())\n                }\n                Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(if(compact)5.dp else 8.dp)){\n                    Button({doLogin(false)},Modifier.weight(1f).heightIn(min=if(compact)32.dp else 40.dp),enabled=!busy,contentPadding=PaddingValues(horizontal=8.dp,vertical=0.dp)){Text(syncText(lang,"login"),maxLines=1)}\n                    OutlinedButton({doLogin(true)},Modifier.weight(1f).heightIn(min=if(compact)32.dp else 40.dp),enabled=!busy,contentPadding=PaddingValues(horizontal=8.dp,vertical=0.dp)){Text(syncText(lang,"register"),maxLines=2)}\n                }\n                if(status.isNotBlank())Text(status,color=if(error)MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary,style=MaterialTheme.typography.bodySmall)\n            }\n        }else{\n            Row(Modifier.fillMaxWidth().padding(horizontal=10.dp,vertical=if(compact)3.dp else 5.dp),verticalAlignment=androidx.compose.ui.Alignment.CenterVertically){\n                Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(if(compact)0.dp else 1.dp)){\n                    Text(syncText(lang,"title"),style=MaterialTheme.typography.titleSmall)\n                    Text(settings.syncEmail,style=MaterialTheme.typography.bodySmall,maxLines=1)\n                    Text(if(status.isNotBlank())status else syncText(lang,"enabled"),color=if(error)MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary,style=MaterialTheme.typography.labelMedium,maxLines=1)\n                }\n                TextButton({CloudSync.logout(settings);logged=false;status=""},enabled=!busy,modifier=Modifier.heightIn(min=if(compact)28.dp else 30.dp),contentPadding=PaddingValues(horizontal=10.dp,vertical=0.dp)){Text(syncText(lang,"logout"),style=MaterialTheme.typography.bodySmall)}\n            }\n        }\n    }\n'''
